// Fictional 24 V training bus. Pure rules shared by terminal UI and verification.
export const LOADS={off:{name:'Isolated',ohms:Infinity,watts:0},receiver:{name:'Receiver',ohms:24,watts:24},fan:{name:'Cooling fan',ohms:12,watts:48},transmitter:{name:'Transmitter',ohms:8,watts:72}};
export const BRANCHES={A:2,B:3,C:1,D:4};
export const CIRCUIT_CLUES={
 bus:{title:'Generator service plate',text:'24 V regulated bus. Continuous and startup limit: 150 W. Current = voltage / resistance. Power = voltage × current. A trip opens the bus; correct the routing and try again.'},
 loads:{title:'Bench resistance measurements',text:'Receiver: 24 Ω. Cooling fan: 12 Ω. Transmitter: 8 Ω steady; startup draws 24 W more. Start with the receiver connected. Cooling is essential for sustained transmission, but may be isolated during startup.'},
 fault:{title:'Insulation test slip',text:'Branches A, B and C pass. D leaks 4 A into a damaged return: isolate D. Branch A fuse: 2 A. Branch C fuse: 1 A. The B fuse rating was copied onto the rooftop dish service label.'},
 roof:{title:'Rooftop service label',text:'Branch B: 3 A maximum. Startup surge is carried by a separate local capacitor; branch fuses see the steady load, but the generator supplies the additional 24 W. Do not duplicate equipment on multiple branches.'}
};
export function createCircuits(){return {version:1,routes:{A:'off',B:'off',C:'off',D:'off'},clues:[],running:false,solved:false,hint:0,attempts:0};}
export function validateCircuits(raw,{legacySolved=false}={}){if(raw===undefined){const c=createCircuits();if(legacySolved){c.routes={A:'fan',B:'transmitter',C:'receiver',D:'off'};c.clues=Object.keys(CIRCUIT_CLUES);c.running=c.solved=true;}return c;}const c=createCircuits();if(!raw||raw.version!==1||!raw.routes||Object.keys(raw.routes).length!==4||!Object.keys(BRANCHES).every(k=>Object.hasOwn(LOADS,raw.routes[k]))||!Array.isArray(raw.clues)||raw.clues.some(k=>!Object.hasOwn(CIRCUIT_CLUES,k))||new Set(raw.clues).size!==raw.clues.length||typeof raw.running!=='boolean'||typeof raw.solved!=='boolean'||!Number.isInteger(raw.hint)||raw.hint<0||raw.hint>3||!Number.isSafeInteger(raw.attempts)||raw.attempts<0)throw Error('Invalid relay circuits');Object.assign(c,raw,{routes:{...raw.routes},clues:[...raw.clues]});if(c.running&&(Object.keys(CIRCUIT_CLUES).some(k=>!c.clues.includes(k))||!evaluateCircuits(c.routes,true).ok)||c.solved&&(!c.running||!evaluateCircuits(c.routes,true).complete))throw Error('Inconsistent relay circuits');return c;}
export function recordCircuitClue(c,id){if(!c.clues.includes(id))c.clues.push(id);}
export function evaluateCircuits(routes,running=false){
 const loads=Object.values(routes).filter(k=>k!=='off'),steady=loads.reduce((sum,k)=>sum+(LOADS[k]?.watts||0),0),peak=steady+(!running&&loads.includes('transmitter')?24:0);
 const fail=message=>({ok:false,complete:false,steady,peak,message});
 if(Object.keys(BRANCHES).some(k=>!Object.hasOwn(LOADS,routes[k])))return fail('Unknown route.');
 if(routes.D!=='off')return fail('GROUND FAULT / D insulation leakage. Bus tripped; isolate the damaged return.');
 if(new Set(loads).size!==loads.length)return fail('PATCH CONFLICT / one device cannot occupy two branches.');
 for(const [id,amps]of Object.entries(BRANCHES))if(LOADS[routes[id]].watts/24>amps)return fail(`BRANCH ${id} OVERCURRENT / compare the fuse rating with the load current.`);
 if(!loads.includes('receiver')||!loads.includes('transmitter'))return fail('CARRIER INCOMPLETE / receiver and transmitter must share the live bus.');
 if(peak>150)return fail(`GENERATOR TRIP / ${peak} W ${running?'steady':'startup'} exceeds 150 W. Review the startup note.`);
 const complete=loads.includes('fan');return {ok:true,complete,steady,peak,message:complete?'STABLE / 144 W. Receiver, transmitter and cooling online.':'CARRIER STARTED / 96 W steady. Restore cooling for sustained transmission.'};
}
export function setCircuitRoute(c,branch,load){if(c.solved||!Object.hasOwn(BRANCHES,branch)||!Object.hasOwn(LOADS,load))return false;c.routes[branch]=load;if(c.running&&!evaluateCircuits(c.routes,true).ok)c.running=false;return true;}
export function energizeCircuits(c){if(c.solved)return {ok:true,complete:true,message:'Bus already commissioned.'};if(Object.keys(CIRCUIT_CLUES).some(k=>!c.clues.includes(k)))return {ok:false,message:'Gather the service plate, resistance readings, insulation slip and rooftop rating before energizing.'};c.attempts++;const result=evaluateCircuits(c.routes,c.running);c.running=result.ok;c.solved=result.ok&&result.complete;return result;}
export const CIRCUIT_HINTS=['Compare the resistance readings with each fuse rating. The damaged branch must remain isolated.','At 24 V the three steady loads total 144 W. Starting all three adds 24 W: 168 W exceeds the 150 W generator. Which load can wait?','Start the receiver and transmitter with cooling isolated. Once startup is over, restore the fan and test again. Match each device current to its branch fuse.'];
export function circuitPanel(c){return `<section class="circuitPanel"><h3>24 V distribution board</h3><p>150 W supply · ${c.solved?'COMMISSIONED':c.running?'CARRIER RUNNING / cooling required':'BUS ISOLATED'} · ${c.attempts} tests</p><div class="settingsGrid">${Object.keys(BRANCHES).map(id=>`<label class="settingRow">Branch ${id} / ${id==='B'&&!c.clues.includes('roof')?'rating obscured':BRANCHES[id]+' A'}<select data-circuit-branch="${id}" ${c.solved?'disabled':''}>${Object.entries(LOADS).map(([k,l])=>`<option value="${k}" ${c.routes[id]===k?'selected':''}>${l.name}</option>`).join('')}</select></label>`).join('')}</div><button data-circuit-test ${c.solved?'disabled':''}>TEST / ENERGIZE</button> <button data-circuit-hint ${c.hint>=3?'disabled':''}>${c.hint?'NEXT HINT':'REQUEST A HINT'}</button>${CIRCUIT_HINTS.slice(0,c.hint).map(t=>`<p class="hint">${t}</p>`).join('')}<details><summary>Recovered measurements (${c.clues.length}/4)</summary>${c.clues.map(id=>`<h4>${CIRCUIT_CLUES[id].title}</h4><p>${CIRCUIT_CLUES[id].text}</p>`).join('')}</details></section>`;}
